import json,copy,hashlib
from pathlib import Path
O=Path(__file__).resolve().parent;R=O.parents[2];P=R/'protocols/neuro-oncology/00806-cisplatin-lomustine-and-vincristine-clv-therapy.json'
p=json.loads((O/'protocol-before/00806.json').read_text());defs=p['input_definitions'];rules=[]
N='https://healthservice.hse.ie/documents/6870/806_V2_CLV_Therapy.pdf'
L='https://www.medac.eu/fileadmin/user_upload/medac-eu/SPCs/common_SPCs/Lomustine_medac-spc-common.pdf'
C='https://assets.hpra.ie/products/Human/27566/Licence_PA2315-081-001_10072026160843.pdf'
def op(f,o,v):return {'field':f,'operator':o,'value':v}
def eq(f,v):return op(f,'==',v)
def missing(f):return op(f,'missing',True)
def allof(*x):return {'all':list(x)}
def anyof(*x):return {'any':list(x)}
def band(f,lo,hi):return allof(op(f,'>=',lo),op(f,'<',hi))
def boolean(label,demo=False,**extra):return dict(label=label,type='boolean',required=False,demo_value=demo,input_role='decision',**extra)
def number(label,unit,demo=0,**extra):return dict(dict(label=label,type='number',required=False,min=0,step=.01,demo_value=demo,unit=unit,input_role='decision'),**extra)
def select(label,options,demo,**extra):return dict(label=label,type='select',required=False,options=[{'value':v,'label':l}for v,l in options],demo_value=demo,input_role='decision',**extra)
def rule(id,when,typ,msg,page='3',components=('whole_regimen',),src='nccp',**extra):
 a=dict(type=typ,components=list(components),message=msg,**extra)
 if typ in ('consultant_review','dose_reduce_one_level','withhold_then_reduce'):a['dose_calculation']='specialist_review'
 if typ=='consultant_review':a.update(show_in_dose_actions=True,block_numeric_dose=True)
 rules.append(dict(id=id,priority=10 if typ in ['contraindicated','permanently_discontinue','omit']else 9 if typ in ['withhold','withhold_then_reduce']else 8,when=when,action=a,source=dict(document={'nccp':'NCCP00806v2','lom':'Lomustine medac common SmPC January2026','cis':'HPRA Accord cisplatin SmPC10July2026'}[src],url={'nccp':N,'lom':L,'cis':C}[src],page=str(page)),explanation=msg))
for k in ['lomustine_renal_band','cisplatin_renal_band','more_than_two_count_delays']:defs.pop(k,None)
defs['assessment_day']=select('Scheduled treatment day',[(1,'Day1: lomustine, cisplatin and vincristine'),(8,'Day8: vincristine only'),(15,'Day15: vincristine only')],1)
defs['cycle_number']=number('CLV cycle number','cycle',1,step=1,min=1,max=99)
defs['high_risk_medulloblastoma_or_pnet_confirmed']=boolean('Consultant confirms adult high-risk medulloblastoma / PNET indication',True,assessment_guidance='This is a diagnosis and risk classification, not a toxicity grade. NCCP examples are not a complete risk algorithm; confirm diagnosis and multidisciplinary plan.')
defs['weeks_since_craniospinal_rt']=number('Weeks since completion of craniospinal radiotherapy before Cycle1','weeks',4)
defs['craniospinal_rt_complete']=boolean('Planned craniospinal radiotherapy completed',True)
defs['crcl_ml_min']=number('Creatinine clearance (CrCl), exact result','mL/min',90,renal_input={'mode':'exact_numeric','exact_value_required':True,'measure':'CrCl'},assessment_guidance='Use measured or locally validated calculated CrCl, not unadjusted eGFR. Preserve decimal values. NCCP cisplatin bands leave49–50 and59–60 gaps; seek review rather than round.')
defs['haemodialysis']=boolean('Receiving haemodialysis')
defs['severe_renal_impairment']=boolean('Severe renal impairment, clinician assessed (NCCP exclusion)')
defs['hepatic_impairment']=select('Liver impairment severity (clinician assessed)',[('none','None'),('mild_moderate','Mild/moderate'),('severe','Severe')],'none',assessment_guidance='NCCP does not define a numeric threshold for severe impairment. Do not infer severity from bilirubin alone.')
defs['bilirubin_fraction']=select('Bilirubin fraction reported',[('total','Total'),('direct','Direct'),('unspecified','Unspecified / uncertain')],'total',assessment_guidance='The NCCP vincristine table does not identify total versus direct bilirubin; confirm the applicable product and local interpretation before a numerical dose.')
defs['bilirubin_umol_l']['label']='Bilirubin result (record fraction separately)'
defs['neuropathy_grade']=select('Current clinician-verified neurotoxicity source grade',[(g,f'Source Grade{g}')for g in range(5)],0,grading_source_label='NCCP00806v2 neurotoxicity table',grading_source_url=N,source_grading_note='The NCCP table does not specify a grading edition or an exact recovery grade. Confirm a clinician-assigned source grade and documented recovery; do not silently convert to CTCAE v5/v6.',assessment_guidance='Grade1: full scheduled vincristine if otherwise suitable; Grade2: withhold until recovery then50% dose; Grade3–4: omit. Recovery and previous reduction require prescriber confirmation.')
defs['prior_vincristine_neurotoxicity_grade']=copy.deepcopy(defs['neuropathy_grade']);defs['prior_vincristine_neurotoxicity_grade']['label']='Highest prior vincristine neurotoxicity source grade requiring modification'
defs['vincristine_neurotoxicity_recovery_confirmed']=boolean('Prescriber confirms recovery from prior Grade2 neurotoxicity')
defs['vincristine_prior_reduction_or_omission']=boolean('Vincristine previously reduced or omitted (retain dose history)')
defs['vincristine_iv_minibag_verified']=boolean('Vincristine IV-only minibag and route safeguards verified',True)
defs['severe_constipation_or_ileus']=boolean('Severe constipation, abdominal distension or possible ileus')
defs['bowel_prophylaxis_plan_confirmed']=boolean('Constipation prevention and monitoring plan confirmed',True)
defs['aprepitant_or_azole_exposure']=boolean('Aprepitant or azole antifungal exposure requiring vincristine interaction review')
defs['interaction_review_needed']=boolean('Unresolved interaction / overlapping neuro-, renal- or marrow toxicity')
defs['antiemetic_plan_confirmed']=boolean('Day1 antiemetic plan confirmed after vincristine interaction review',True)
defs['baseline_tests_complete']=boolean('Baseline FBC, renal/liver profile and indicated hearing/PFT assessments reviewed',True)
defs['scheduled_tests_complete']=boolean('Current FBC, renal/liver/electrolytes and indicated hearing/PFT monitoring reviewed',True)
defs['weekly_counts_plan_confirmed']=boolean('Weekly blood-count plan for at least6weeks after lomustine confirmed',True)
defs['lomustine_supply_and_single_dose_verified']=boolean('Unlicensed lomustine supply and single Day1 dose instructions verified',True)
defs['lomustine_days_since_previous_dose']=number('Days since previous lomustine dose (repeat-course assessment)','days',42,step=1)
defs['lomustine_prior_count_delay']=boolean('A previous lomustine count delay requires recovery / new baseline-dose review')
defs['lomustine_count_delay_number']=number('Number of lomustine count delays','delays',0,step=1)
defs['lomustine_dose_history_confirmed']=boolean('Original, previous and new baseline lomustine doses reconciled with pharmacy',True)
defs['lomustine_prior_reduction']=boolean('Previous lomustine dose reduction (do not automatically re-escalate)')
defs['lomustine_nadir_review_complete']=boolean('Prior-cycle nadir and delayed blood counts reviewed before repeat lomustine',True)
defs['wbc_nadir_x10e9_l']=number('Lowest WBC in preceding cycle (not ANC)','×10⁹/L',4)
defs['platelet_nadir_x10e9_l']=number('Lowest platelets in preceding cycle','×10⁹/L',150)
defs['wbc_x10e9_l']=number('Current total white cell count (not ANC)','×10⁹/L',5)
defs['cumulative_lomustine_mg_m2']=number('Total previous lifetime lomustine exposure','mg/m²',0)
defs['projected_lomustine_cumulative_mg_m2']=number('Pharmacy-verified lifetime lomustine total INCLUDING proposed next dose','mg/m²',75)
defs['lomustine_cumulative_history_confirmed']=boolean('All prior lomustine exposure and proposed-dose total reconciled',True)
defs['fvc_percent_predicted']=number('Baseline forced vital capacity (FVC)','%predicted',95,max=250)
defs['dlco_percent_predicted']=number('Baseline carbon-monoxide diffusing capacity (DLCO)','%predicted',95,max=250)
defs['severe_myelosuppression']=boolean('Severe bone-marrow depression, clinician assessed')
defs['wheat_allergy']=boolean('Wheat allergy (lomustine medac contains wheat starch)')
defs['prior_nitrosourea_nonresponse']=boolean('Previous tumour nonresponse to another nitrosourea')
defs['live_vaccine_exposure']=boolean('Planned/current live vaccine during immunosuppressive treatment')
defs['new_hearing_symptoms']=boolean('New tinnitus, hearing loss or vestibular symptoms')
defs['new_renal_or_electrolyte_abnormality']=boolean('New clinically important renal dysfunction or electrolyte disturbance')
defs['cisplatin_product_and_local_plan_confirmed']=boolean('Pharmacy reconciled cisplatin product, infusion duration, hydration and any renal exception',True)
defs['preexisting_renal_impairment']=boolean('Pre-existing renal impairment requiring cisplatin product contraindication review')
defs['anc_x10e9_l']['label']='Current pre-dose absolute neutrophil count (not preceding nadir)'
defs['platelets_x10e9_l']['label']='Current pre-dose platelet count (not preceding nadir)'
defs['antifungal_plan_confirmed']=boolean('Local antifungal prophylaxis plan reviewed, avoiding vincristine/azole interaction',True)
# Source-specific independent eligibility and urgent concerns.
rule('ECOG_OUTSIDE_PATHWAY',op('ecog','>',2),'consultant_review','ECOG above2 is outside the published eligibility range; confirm benefit, risk and the authorised plan.',2)
rule('ADULT_INDICATION',op('age_years','<',18),'consultant_review','This is the adult high-risk medulloblastoma/PNET protocol. Obtain the appropriate paediatric plan rather than infer eligibility.',2)
rule('AGE_GT40',op('age_years','>',40),'contraindicated','Age over40 is an explicit exclusion in NCCP00806; review an alternative regimen.',2)
rule('INDICATION',eq('high_risk_medulloblastoma_or_pnet_confirmed',False),'consultant_review','Confirm the diagnosis and high-risk indication. Do not apply the glioma schedule or an incomplete automated risk definition.',2)
for f,id in [('hypersensitivity','HYPERSENSITIVITY'),('pregnancy','PREGNANCY'),('breastfeeding','BREASTFEEDING'),('significant_hearing_impairment_or_tinnitus','HEARING'),('severe_renal_impairment','SEVERE_RENAL_EXCLUSION')]:rule(id,eq(f,True),'contraindicated','NCCP exclusion: '+defs[f]['label']+'. Resolve the regimen choice with the consultant.',2)
rule('ACTIVE_INFECTION',eq('active_infection',True),'withhold','Urgently review active infection before further cytotoxic treatment, including delayed marrow suppression and sepsis risk. This is a clinical safety review, not a new numeric NCCP threshold.','4.4',src='lom')
rule('CYCLE_LIMIT',op('cycle_number','>',8),'consultant_review','NCCP plans eight42-day cycles. Confirm any proposed course beyond eight with the consultant.',1)
rule('RT_INCOMPLETE',eq('craniospinal_rt_complete',False),'consultant_review','CLV follows completion of craniospinal radiotherapy; confirm sequencing before starting.',1)
rule('RT_INTERVAL',allof(eq('cycle_number',1),anyof(op('weeks_since_craniospinal_rt','<',4),op('weeks_since_craniospinal_rt','>',6))),'consultant_review','Cycle1 is scheduled4–6weeks after craniospinal radiotherapy; timing outside this range requires explicit review.',1)
rule('RT_TIMING_MISSING',allof(eq('cycle_number',1),anyof(missing('weeks_since_craniospinal_rt'),missing('craniospinal_rt_complete'))),'consultant_review','Confirm completion and the4–6week interval after craniospinal radiotherapy before Cycle1.',1)
rule('BASELINE_TESTS',allof(eq('cycle_number',1),eq('baseline_tests_complete',False)),'consultant_review','Review baseline FBC, renal/liver function and indicated audiology/CrCl and pulmonary testing; product SmPCs add electrolyte, hearing and pulmonary monitoring requirements.',2)
rule('SCHEDULED_TESTS',eq('scheduled_tests_complete',False),'consultant_review','Obtain the currently due blood, renal/liver/electrolyte and indicated hearing/pulmonary assessments before prescribing. No fixed MRI interval is supplied by this NCCP protocol.',2)
# Current counts versus history: no nadir/recovery inference from a single current result.
for f,b,id in [('anc_x10e9_l',1,'ANC_LT1'),('platelets_x10e9_l',80,'PLT_LT80')]:rule(id,op(f,'<',b),'withhold_then_reduce','Do not give lomustine with these current counts. NCCP requires recovery to ANC≥1 AND platelets≥100; after a qualifying delay it specifies80% of the original dose as the new full dose. Confirm original/previous dose, cumulative nadir and all other restrictions before prescribing.',3,('lomustine',))
rule('PLT_80_99',band('platelets_x10e9_l',80,100),'consultant_review','Platelets80 to<100 are not assigned a new-dose row when ANC≥1 in NCCP Table1. Do not round99.5 to100 or infer a dose. For recovery after a documented hold, platelets must reach100.',3,('lomustine',))
rule('COUNT_RECOVERY_INCOMPLETE',allof(eq('lomustine_prior_count_delay',True),anyof(op('anc_x10e9_l','<',1),op('platelets_x10e9_l','<',100))),'withhold','A prior count delay remains unresolved until BOTH ANC≥1 and platelets≥100. Do not apply the80% restart to an unrecovered count.',3,('lomustine',))
rule('COUNT_HISTORY_MISSING',allof(eq('lomustine_prior_count_delay',True),anyof(missing('anc_x10e9_l'),missing('platelets_x10e9_l'))),'consultant_review','Both current ANC and platelet recovery results are required before reviewing a lomustine restart after a count delay.',3,('lomustine',))
rule('COUNT_RECOVERED_REVIEW',allof(eq('lomustine_prior_count_delay',True),op('anc_x10e9_l','>=',1),op('platelets_x10e9_l','>=',100)),'consultant_review','Counts meet the NCCP recovery targets. Reconcile80% of the documented original lomustine dose as the new full dose, prior reductions, nadir, organ function and delay number. Do not automatically multiply a previously reduced dose or return to75mg/m².',3,('lomustine',))
rule('DELAYS_GT2',op('lomustine_count_delay_number','>',2),'consultant_review','More than two count delays requires the prescribing clinician to review the treatment plan.',3,('lomustine',))
rule('LOM_DOSE_HISTORY',anyof(eq('lomustine_dose_history_confirmed',False),eq('lomustine_prior_reduction',True)),'consultant_review','Retain the documented original, previous and new full lomustine doses; recovery does not authorise re-escalation. The NCCP80% count-delay and75% renal instructions must not be multiplied without a consultant/pharmacy decision.',3,('lomustine',))
rule('LOM_REPEAT_TOO_SOON',op('lomustine_days_since_previous_dose','<',42),'withhold','Do not repeat lomustine before42days: marrow toxicity is delayed and cumulative. The NCCP regimen uses ONE oral Day1 dose, not a daily course.','4.2–4.4',('lomustine',),'lom')
rule('LOM_HISTORY_REQUIRED',allof(op('cycle_number','>',1),anyof(missing('lomustine_days_since_previous_dose'),missing('lomustine_nadir_review_complete'),missing('lomustine_dose_history_confirmed'),missing('lomustine_cumulative_history_confirmed'))),'consultant_review','Before repeat lomustine confirm the interval, preceding nadir, all prior dose changes and lifetime cumulative exposure. Normal current counts alone are insufficient.','4.2–4.4',('lomustine',),'lom')
rule('LOM_NADIR_REVIEW',eq('lomustine_nadir_review_complete',False),'consultant_review','Review preceding-cycle nadirs and delayed recovery before repeat lomustine; the current SmPC bases changes on previous response and is not identical to NCCP Table1.','4.2',('lomustine',),'lom')
rule('LOM_NADIR_LOW',anyof(op('wbc_nadir_x10e9_l','<',3),op('platelet_nadir_x10e9_l','<',75)),'consultant_review','Prior nadir crosses a lomustine product dose-adjustment band even if present counts recovered. The SmPC uses WBC and prior dose, while NCCP uses ANC and original-dose80% after a delay. Resolve the regimen/product differences; do not automatically calculate a percentage.','4.2',('lomustine',),'lom')
rule('LOM_NADIR_OVERLAP',band('platelet_nadir_x10e9_l',24,25),'consultant_review','The current common SmPC platelet nadir rows overlap from24 to<25×10⁹/L (70% row starts24;50% row extends below25). This is unresolved source ambiguity, not a numeric-dose calculation.','4.2',('lomustine',),'lom')
rule('LOM_WBC_RECOVERY',op('wbc_x10e9_l','<',4),'consultant_review','The lomustine SmPC requires current WBC≥4 before repeating, while NCCP Table1 uses ANC≥1. WBC and ANC are distinct; resolve recovery and the product-specific plan before further lomustine.','4.2',('lomustine',),'lom')
rule('LOM_WEEKLY_MONITORING',eq('weekly_counts_plan_confirmed',False),'consultant_review','Arrange weekly counts for at least six weeks after each lomustine dose, including the delayed nadir and any extended recovery.','4.4',('lomustine',),'lom')
rule('LOM_SINGLE_DOSE',eq('lomustine_supply_and_single_dose_verified',False),'withhold','Verify unlicensed-drug supply with the dispensing pharmacy and ONE prescribed Day1 lomustine dose. Do not repeat after vomiting or take extra doses without oncology advice.',1,('lomustine',))
rule('LOM_CUMULATIVE_EXCEEDED',op('projected_lomustine_cumulative_mg_m2','>',1000),'withhold','The current lomustine SmPC maximum cumulative exposure is1000mg/m². The proposed lifetime total exceeds it: do not give the proposed lomustine dose; seek consultant/pharmacy review.','4.2–4.4',('lomustine',),'lom')
rule('LOM_CUMULATIVE_REACHED',op('cumulative_lomustine_mg_m2','>=',1000),'withhold','Previous lifetime lomustine exposure has reached or exceeded1000mg/m². Further positive dosing would exceed the product maximum; seek consultant/pharmacy review.','4.2–4.4',('lomustine',),'lom')
rule('LOM_CUMULATIVE_LIMIT',eq('projected_lomustine_cumulative_mg_m2',1000),'consultant_review','The proposed lifetime total reaches the1000mg/m² maximum exactly. Recheck all prior exposure, proposed dose and pulmonary risk; this is not automatic clearance for the final dose.','4.2–4.4',('lomustine',),'lom')
rule('LOM_CUMULATIVE_HISTORY',eq('lomustine_cumulative_history_confirmed',False),'consultant_review','Reconcile lifetime lomustine exposure including previous regimens and the proposed next dose before prescribing.','4.2–4.4',('lomustine',),'lom')
# Renal values shared by all components; decimal gaps are never rounded.
rule('LOM_30_50',allof(op('crcl_ml_min','>=',30),op('crcl_ml_min','<=',50)),'consultant_review','NCCP Table2 specifies75% of the original lomustine dose at CrCl30–50mL/min. Confirm dialysis status, original/current dose and any marrow reduction; do not combine reductions automatically.',3,('lomustine',))
rule('LOM_LT30',anyof(op('crcl_ml_min','<',30),eq('haemodialysis',True)),'withhold','Lomustine is not recommended by NCCP at CrCl<30mL/min or during haemodialysis. Withhold the proposed dose for specialist review; the separate severe-renal exclusion remains applicable.',3,('lomustine',))
rule('LOM_SEVERE_HEPATIC',eq('hepatic_impairment','severe'),'withhold','NCCP does not recommend lomustine in severe hepatic impairment. No numeric definition of severe is supplied; obtain consultant/pharmacy review.',3,('lomustine',))
rule('LOM_MILD_MOD_HEPATIC',eq('hepatic_impairment','mild_moderate'),'proceed_with_caution','NCCP expects no hepatic dose adjustment for mild/moderate impairment, but abnormal liver tests, eligibility and other dose restrictions still require review.',3,('lomustine',))
for lo,hi,pc,id in [(40,49,50,'CIS_40_49'),(50,59,75,'CIS_50_59')]:rule(id,allof(op('crcl_ml_min','>=',lo),op('crcl_ml_min','<=',hi)),'consultant_review',f'NCCP specifies{pc}% of the original cisplatin dose at CrCl{lo}–{hi}mL/min. The current Accord SmPC contraindicates pre-existing renal impairment; reconcile the actual product and renal exception with the consultant/pharmacist before a dose. No automatic calculation.',3,('cisplatin',))
rule('CIS_RENAL_GAP',anyof(allof(op('crcl_ml_min','>',49),op('crcl_ml_min','<',50)),allof(op('crcl_ml_min','>',59),op('crcl_ml_min','<',60))),'consultant_review','The printed NCCP cisplatin bands leave fractional CrCl49–50 and59–60mL/min unallocated. Do not round or select a percentage without specialist interpretation.',3,('cisplatin',))
rule('CIS_LT40',op('crcl_ml_min','<',40),'withhold','Cisplatin is not recommended by NCCP below CrCl40mL/min. Seek specialist review of eligibility and alternatives.',3,('cisplatin',))
rule('CIS_DIALYSIS',eq('haemodialysis',True),'consultant_review','NCCP says50% of the original cisplatin dose may be considered during haemodialysis. This conditional exception needs specialist pharmacy/renal review of product contraindications, schedule and dialysis timing; no automatic dose.',3,('cisplatin',))
rule('RENAL_DIALYSIS_UNKNOWN',allof(op('crcl_ml_min','>=',0),missing('haemodialysis')),'consultant_review','Confirm haemodialysis status before interpreting the renal table; a reported CrCl alone does not establish the non-dialysis pathway.',3,('cisplatin','lomustine'))
rule('CIS_PREEXISTING_RENAL',eq('preexisting_renal_impairment',True),'consultant_review','The current Accord cisplatin product contraindicates pre-existing renal impairment, while NCCP lists reduced-dose bands. Resolve the actual product and consultant-approved plan explicitly.','4.3',('cisplatin',),'cis')
rule('CIS_PRODUCT_PLAN',eq('cisplatin_product_and_local_plan_confirmed',False),'withhold','Reconcile the actual cisplatin product and local administration plan: NCCP lists a1-hour infusion, whereas the current Accord SmPC describes6–8hours and different hydration/diuresis instructions. Do not generate a prescription from an unresolved source conflict.','4.2–4.4',('cisplatin',),'cis')
rule('HYDRATION',eq('cisplatin_hydration_and_magnesium_ready',False),'withhold','Confirm pre/post cisplatin hydration, magnesium/electrolytes, fluid status and urine-output plan under local policy before administration. NCCP does not recommend routine furosemide without fluid excess.','1,4',('cisplatin',))
rule('CIS_NEW_RENAL',eq('new_renal_or_electrolyte_abnormality',True),'withhold','Investigate and correct clinically important renal/electrolyte abnormalities before further cisplatin; review cumulative nephrotoxicity and the individual hydration plan.','4.4',('cisplatin',),'cis')
rule('CIS_NEW_HEARING',eq('new_hearing_symptoms',True),'withhold','New tinnitus, hearing or balance change needs assessment and audiology before further cisplatin; significant hearing impairment/tinnitus is a separate NCCP regimen exclusion.','4.4',('cisplatin',),'cis')
rule('CIS_NEUROTOXICITY',op('neuropathy_grade','>=',2),'consultant_review','Neurological toxicity also requires review of cisplatin, which can cause cumulative and irreversible neuropathy. The NCCP vincristine percentage is not a cisplatin reduction algorithm.','4.4',('cisplatin',),'cis')
# Vincristine bilirubin and neurotoxicity retain history and source uncertainty.
rule('VIN_BILI',op('bilirubin_umol_l','>',51),'consultant_review','NCCP specifies50% of original vincristine when bilirubin is above51μmol/L, but does not name the bilirubin fraction. Confirm fraction, actual product, previous dose/cap and concurrent neurotoxicity before a numerical dose.',3,('vincristine',))
rule('VIN_BILI_FRACTION',allof(op('bilirubin_umol_l','>',51),anyof(missing('bilirubin_fraction'),eq('bilirubin_fraction','unspecified'))),'consultant_review','The elevated bilirubin result has no confirmed fraction. NCCP does not specify total versus direct; ask pharmacy to reconcile the laboratory value and current product instructions.',3,('vincristine',))
rule('VIN_NEURO_G2',eq('neuropathy_grade',2),'withhold_then_reduce','Withhold vincristine for source Grade2 neurotoxicity until recovery, then review the source50% dose. NCCP does not specify an exact recovery grade or how to combine previous reductions; do not automatically restart.',4,('vincristine',))
rule('VIN_NEURO_G34',op('neuropathy_grade','>=',3),'omit','Omit vincristine for source Grade3–4 neurotoxicity; review symptoms and the wider regimen with the consultant.',4,('vincristine',))
rule('VIN_PRIOR_G2_RECOVERY',allof(eq('prior_vincristine_neurotoxicity_grade',2),eq('vincristine_neurotoxicity_recovery_confirmed',True)),'consultant_review','Prior Grade2 neurotoxicity requires confirmed recovery before the source50% vincristine restart. Reconcile current symptoms, previous/capped dose and hepatic adjustments; recovery alone must not restore the original full dose.',4,('vincristine',))
rule('VIN_PRIOR_G2_UNRECOVERED',allof(eq('prior_vincristine_neurotoxicity_grade',2),eq('vincristine_neurotoxicity_recovery_confirmed',False)),'withhold','Prior Grade2 neurotoxicity has not recovered; continue withholding vincristine even if a different current grade was entered.',4,('vincristine',))
rule('VIN_PRIOR_G2_UNKNOWN',allof(eq('prior_vincristine_neurotoxicity_grade',2),missing('vincristine_neurotoxicity_recovery_confirmed')),'consultant_review','Confirm recovery from prior Grade2 neurotoxicity before any vincristine restart; a missing recovery assessment is not recovery.',4,('vincristine',))
rule('VIN_PRIOR_G34',op('prior_vincristine_neurotoxicity_grade','>=',3),'consultant_review','A previous Grade3–4 event required vincristine omission. Normal current symptoms do not establish a supported restart pathway; obtain an explicit consultant plan.',4,('vincristine',))
rule('VIN_PRIOR_REDUCTION',eq('vincristine_prior_reduction_or_omission',True),'consultant_review','Preserve previous vincristine reductions or omissions. Do not use the reference1.5mg/m²(max2mg) as an automatic restart dose.',4,('vincristine',))
rule('VIN_ROUTE',eq('vincristine_iv_minibag_verified',False),'withhold','Verify IV-only vincristine in the prescribed50mL minibag and all local vinca-alkaloid route safeguards before administration. Never administer intrathecally.',1,('vincristine',))
rule('VIN_BOWEL_URGENT',eq('severe_constipation_or_ileus',True),'withhold','Urgently assess severe constipation, abdominal distension or possible ileus before further vincristine; review autonomic neurotoxicity, hydration and the bowel plan.',4,('vincristine',))
