# Keep clinical prose legible; schema identifiers and URLs remain untouched.
import re
def clean(x,key=''):
 if isinstance(x,dict):return {k:clean(v,k) for k,v in x.items()}
 if isinstance(x,list):return [clean(v,key) for v in x]
 if isinstance(x,str) and key in ['label','message','explanation','note','schedule_summary','assessment_guidance','source_grading_note','grading_source_label','scope_note','dose_modification_note','issue','document']:
  x=re.sub(r'([A-Za-z])(?=\d)',r'\1 ',x);x=re.sub(r'(\d)(?=[A-Za-z])',r'\1 ',x)
  x=re.sub(r'\bv (\d)',r'v\1',x);x=re.sub(r'\bCYP (\d+) A (\d+)',r'CYP\1A\2',x)
  x=re.sub(r'([≥≤<>])',r' \1 ',x);x=re.sub(r' +',' ',x)
 return x
p=clean(p)
